package odc;
import java.util.*;
import net.minecraft.nbt.*;
import net.minecraft.world.World;
import net.minecraft.world.storage.WorldSavedData;
/** Server-authoritative persistent jobs and wallets. Scope: task anchor controller + owner. */
public final class TaskData extends WorldSavedData {
    static final String KEY="odc_compute_v043"; static final String[] COINS={"NCoin","KriptoCoin"};static final String[] TYPES={"KriptoCoin / CoreHash","KriptoCoin / ParallelHash","KriptoCoin / MemoryHash","Bank service","AI training","AI inference"};
    static final class Job extends TaskEngine.Task { UUID anchor,owner; int work,usedCPU,usedGPU,usedRAM,usedDisk,usedNet;long remainder,earned;String name;boolean full; Job(int id,int type,UUID a,UUID o){super(id,type);anchor=a;owner=o;name=TYPES[type]+" #"+id;} }
    final List<Job> jobs=new ArrayList<>();final Map<UUID,Integer> groups=new HashMap<>();final Map<UUID,long[]> wallets=new HashMap<>();final List<String> log=new ArrayList<>();int next=0;long ticks;int[] difficulty={100,100},rate={1000,1500};long[] work=new long[2];
    public TaskData(){super(KEY);}public TaskData(String name){super(name);}
    static TaskData get(World w){net.minecraft.world.storage.MapStorage s=w.getPerWorldStorage();TaskData d=(TaskData)s.getOrLoadData(TaskData.class,KEY);if(d==null){d=new TaskData();s.setData(KEY,d);}return d;}
    long[] wallet(UUID a){return wallets.computeIfAbsent(a,k->new long[2]);}
    long credit(UUID a,int coin,long v){long paid=a==null?0:EconomyEngine.credit(wallet(a),coin,v);if(paid>0)markDirty();return paid;}
    boolean transfer(UUID from,UUID to,int coin,long v){boolean ok=!from.equals(to)&&EconomyEngine.transfer(wallet(from),wallet(to),coin,v);if(ok)markDirty();return ok;}
    boolean exchange(UUID a,int coin,long amount){boolean ok=coin>=1&&coin<2&&EconomyEngine.exchange(wallet(a),coin,amount,rate[coin]);if(ok)markDirty();return ok;}
    void clock(){ticks++;if(ticks%60==0){for(int i=0;i<2;i++){difficulty[i]=EconomyEngine.difficulty(difficulty[i],work[i]);work[i]=0;rate[i]=EconomyEngine.rate(rate[i],ticks,i);}}markDirty();}
    void event(UUID owner,String s){log.add(owner+"|["+ticks+"s] "+s);if(log.size()>64)log.remove(0);markDirty();}
    List<String> eventsFor(UUID owner){List<String> out=new ArrayList<>();String prefix=owner+"|";for(String l:log)if(l.startsWith(prefix))out.add(l.substring(prefix.length()));return out;}
    void reward(Job j,int output){if(output<=0||!j.enabled)return;if(j.type<3){work[1]=Math.min(Long.MAX_VALUE-output,work[1])+output;long micro=EconomyEngine.microReward(output,difficulty[1],ODC.rewardDivisor)+j.remainder;j.earned=credit(j.anchor,1,micro/1000);j.remainder=micro%1000;}else if(j.type==TaskEngine.BANK||j.type==TaskEngine.INFERENCE)j.earned=credit(j.anchor,0,output*(j.type==TaskEngine.BANK?2L:3L));else if(j.progress<EconomyEngine.AI_GOAL){j.progress=EconomyEngine.progress(j.progress,output);if(j.progress==EconomyEngine.AI_GOAL){j.earned=credit(j.anchor,0,EconomyEngine.AI_REWARD);j.enabled=false;event(j.owner,"AI completed #"+j.id);}}markDirty();}
    @Override public NBTTagCompound writeToNBT(NBTTagCompound n){n.setInteger("Next",next);n.setLong("Ticks",ticks);n.setIntArray("Diff",difficulty);n.setIntArray("Rate",rate);for(int i=0;i<2;i++)n.setLong("Work"+i,work[i]);NBTTagList js=new NBTTagList();for(Job j:jobs){NBTTagCompound x=new NBTTagCompound();x.setInteger("Id",j.id);x.setInteger("Type",j.type);x.setString("Name",j.name);x.setUniqueId("Anchor",j.anchor);x.setUniqueId("Owner",j.owner);x.setIntArray("Req",new int[]{j.priority,j.cpu,j.gpus,j.ram,j.net,j.group,j.disk});x.setBoolean("Strict",j.strict);x.setBoolean("Auto",j.auto);x.setBoolean("Enabled",j.enabled);x.setLong("Progress",j.progress);x.setLong("Remainder",j.remainder);NBTTagList ms=new NBTTagList();for(Map.Entry<UUID,TaskEngine.Limit> e:j.manual.entrySet()){NBTTagCompound m=new NBTTagCompound();m.setUniqueId("Id",e.getKey());m.setInteger("CPU",e.getValue().cpu);m.setInteger("GPU",e.getValue().mask);m.setInteger("RAM",e.getValue().ram);m.setInteger("NET",e.getValue().net);m.setInteger("Disk",e.getValue().disk);ms.appendTag(m);}x.setTag("Manual",ms);js.appendTag(x);}n.setTag("Jobs",js);
        NBTTagList ws=new NBTTagList();for(Map.Entry<UUID,long[]> e:wallets.entrySet()){NBTTagCompound x=new NBTTagCompound();x.setUniqueId("Id",e.getKey());for(int i=0;i<2;i++)x.setLong("C"+i,e.getValue()[i]);ws.appendTag(x);}n.setTag("Wallets",ws);NBTTagList gs=new NBTTagList();for(Map.Entry<UUID,Integer> e:groups.entrySet()){NBTTagCompound x=new NBTTagCompound();x.setUniqueId("Id",e.getKey());x.setInteger("G",e.getValue());gs.appendTag(x);}n.setTag("Groups",gs);NBTTagList logs=new NBTTagList();for(String l:log)logs.appendTag(new NBTTagString(l));n.setTag("Log",logs);return n;}
    @Override public void readFromNBT(NBTTagCompound n){next=Math.max(0,n.getInteger("Next"));ticks=n.getLong("Ticks");int[] a=n.getIntArray("Diff"),b=n.getIntArray("Rate");if(a.length==2)difficulty=a;if(b.length==2)rate=b;for(int i=0;i<2;i++)work[i]=Math.max(0,n.getLong("Work"+i));jobs.clear();NBTTagList js=n.getTagList("Jobs",10);for(int i=0;i<js.tagCount();i++){NBTTagCompound x=js.getCompoundTagAt(i);int type=x.getInteger("Type");if(type<0||type>5||!x.hasUniqueId("Anchor")||!x.hasUniqueId("Owner"))continue;Job j=new Job(x.getInteger("Id"),type,x.getUniqueId("Anchor"),x.getUniqueId("Owner"));int[] q=x.getIntArray("Req");if(q.length==7){j.priority=q[0];j.cpu=q[1];j.gpus=q[2];j.ram=q[3];j.net=q[4];j.group=q[5];j.disk=q[6];}if(x.hasKey("Name"))j.name=x.getString("Name");j.strict=x.getBoolean("Strict");j.auto=x.getBoolean("Auto");j.enabled=x.getBoolean("Enabled");j.progress=x.getLong("Progress");j.remainder=Math.max(0,Math.min(999,x.getLong("Remainder")));NBTTagList ms=x.getTagList("Manual",10);for(int k=0;k<ms.tagCount();k++){NBTTagCompound m=ms.getCompoundTagAt(k);if(m.hasUniqueId("Id")){TaskEngine.Limit l=new TaskEngine.Limit(m.getInteger("CPU"),m.getInteger("GPU"));l.ram=m.hasKey("RAM")?m.getInteger("RAM"):Integer.MAX_VALUE;l.net=m.hasKey("NET")?m.getInteger("NET"):Integer.MAX_VALUE;l.disk=m.hasKey("Disk")?m.getInteger("Disk"):Integer.MAX_VALUE;j.manual.put(m.getUniqueId("Id"),l);}}jobs.add(j);next=Math.max(next,j.id+1);}wallets.clear();NBTTagList ws=n.getTagList("Wallets",10);for(int i=0;i<ws.tagCount();i++){NBTTagCompound x=ws.getCompoundTagAt(i);if(x.hasUniqueId("Id")){long[] v=wallet(x.getUniqueId("Id"));for(int k=0;k<2;k++)v[k]=Math.max(0,x.getLong("C"+k));}}groups.clear();NBTTagList gs=n.getTagList("Groups",10);for(int i=0;i<gs.tagCount();i++){NBTTagCompound x=gs.getCompoundTagAt(i);if(x.hasUniqueId("Id"))groups.put(x.getUniqueId("Id"),x.getInteger("G"));}log.clear();NBTTagList logs=n.getTagList("Log",8);for(int i=0;i<logs.tagCount();i++)log.add(logs.getStringTagAt(i));}
}
